SELECT p.id AS product_id, p.name,p.grade,p.charge_name AS productChargeName,p.project_status,p.brand_name, p.approval_status,pi.charge_name AS projectChargeName ,pi.end_time FROM product_info p INNER JOIN project_info pi ON p.id=pi.product_id WHERE P.category_id=#{params.categoryId}
P.name LIKE concat('%',#{params.searchKeyword},'%')
AND P.project_status IN
#{state}
